-- consumer, one transaction per message
BEGIN;
  INSERT INTO processed(msg_id, at) VALUES (:msg_id, now())
    ON CONFLICT (msg_id) DO NOTHING;
  -- zero rows affected means already processed: skip the effect
  IF inserted THEN
    UPDATE balances SET amount = amount + :delta WHERE id = :acct;
  END IF;
COMMIT;

window sizing: rows = message_rate * retention_seconds
   20000 msg/s * 7 days = 1.21e10 rows    infeasible
   20000 msg/s * 1 hour = 7.2e7 rows      ~2.9 GB at 40 B/row
Beyond the window, a redelivery re-executes.

The dual-write problem:
  BEGIN; UPDATE orders SET state='paid'; COMMIT;
  broker.publish(OrderPaid)      <- crash here: state changed,
                                    nobody was told. Forever.

The outbox:
  BEGIN;
    UPDATE orders SET state='paid' WHERE id = :id;
    INSERT INTO outbox(id, topic, payload, created_at)
      VALUES (gen_random_uuid(), 'orders', :payload, now());
  COMMIT;                        <- one atomic write

  -- separate relay, at-least-once by construction
  SELECT * FROM outbox WHERE published_at IS NULL
    ORDER BY created_at LIMIT 100 FOR UPDATE SKIP LOCKED;
